cd /tmp/vally-eval-reFEqh && mkdir -p src test && cat > src/checkout.mjs <<'EOF'
export class ExpiredPromotionError extends Error {
  constructor(code, expiresAt) {
    super(`Promotion ${code} expired at ${expiresAt.toISOString()}`);
    this.name = 'ExpiredPromotionError';
    this.code = code;
    this.expiresAt = expiresAt;
  }
}

// Policy is provisional: product has not decided reject vs ignore vs confirm.
export function checkout({ items, promotion }, now = new Date()) {
  const subtotal = items.reduce((sum, i) => sum + i.price * i.quantity, 0);
  let discount = 0;
  if (promotion) {
    if (promotion.expiresAt <= now) {
      throw new ExpiredPromotionError(promotion.code, promotion.expiresAt);
    }
    discount = Math.round(subtotal * promotion.percentOff) / 100;
  }
  return { subtotal, discount, total: subtotal - discount };
}
EOF
cat > test/checkout.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkout, ExpiredPromotionError } from '../src/checkout.mjs';

const now = new Date('2026-11-25T12:00:00Z');
const items = [{ price: 50, quantity: 2 }];
const promo = (expiresAt) => ({ code: 'SAVE10', percentOff: 10, expiresAt });

test('valid promotion applies discount', () => {
  const r = checkout({ items, promotion: promo(new Date('2026-12-01T00:00:00Z')) }, now);
  assert.deepEqual(r, { subtotal: 100, discount: 10, total: 90 });
});

test('no promotion charges full price', () => {
  assert.equal(checkout({ items }, now).total, 100);
});

test('expired promotion rejects order with ExpiredPromotionError', () => {
  assert.throws(
    () => checkout({ items, promotion: promo(new Date('2026-11-01T00:00:00Z')) }, now),
    (e) => e instanceof ExpiredPromotionError && e.code === 'SAVE10',
  );
});

test('promotion expiring exactly now is expired', () => {
  assert.throws(() => checkout({ items, promotion: promo(now) }, now), ExpiredPromotionError);
});
EOF
node --test 2>&1 | tail -8

